use super::*;
fn fixture()->Vec<u8>{include_bytes!("../../../../tests/progress/phone-v25.dat").to_vec()}
fn advanced()->Progress{let b=fixture();let mut p=Decoder::parse(&b).unwrap().progress().unwrap();p.classic.stage=1;p.classic.level=2;p.nights.stage=12;p.nights.level=3;p.classic.trophies.insert(0);p.classic.cleared.insert("stage1".into());p.nights.aced.insert("stage12".into());p}
#[test]fn synthetic_profile_roundtrip_preserves_every_byte(){let b=fixture();let d=Decoder::parse(&b).unwrap();assert_eq!(d.apply(&d.progress().unwrap()).unwrap(),b);}
#[test]fn merge_is_idempotent_commutative_and_keeps_unrelated_fields(){let b=fixture();let d=Decoder::parse(&b).unwrap();let a=d.progress().unwrap();let mut b=a.clone();b.classic.stage=2;b.classic.level=0;b.nights.cleared.insert("stage13".into());let c=advanced();assert_eq!(a.merged(&c).merged(&b),a.merged(&b).merged(&c));let m=b.merged(&c);assert_eq!(m,m.merged(&m));assert_eq!((m.classic.stage,m.classic.level),(2,0));let output=d.apply(&m).unwrap();let other=Decoder::parse(&output).unwrap();assert_eq!(other.progress().unwrap(),m);for k in [0x18,0x1c,0x188,0x204,0x294,0x298,0x84,0x344,0x348,0xffff]{assert_eq!(d.field_bytes(k),other.field_bytes(k));}}
#[test]fn every_truncated_profile_and_future_versions_are_rejected(){let b=fixture();for n in 0..b.len(){assert!(Decoder::parse(&b[..n]).is_err(),"accepted truncation {n}");}let mut extra=b.clone();extra.push(0);assert!(Decoder::parse(&extra).is_err());extra[0]=26;assert!(Decoder::parse(&extra).is_err());let mut v=advanced().document("Tester");v["schema"]=json!(3);assert!(Progress::parse(&v).is_err());v["schema"]=json!(2);v["classic"]["furthest_stage"]=json!(100);assert!(Progress::parse(&v).is_err());}
#[test]fn incoming_schema_cannot_carry_local_state_or_ambiguous_levels(){let mut v=advanced().document("Tester");v["original_save"]=json!("opaque data");assert!(Progress::parse(&v).is_err());v.as_object_mut().unwrap().remove("original_save");v["classic"]["cleared_levels"]=json!(["stage1","STAGE1"]);assert!(Progress::parse(&v).is_err());v["classic"]["cleared_levels"]=json!(["stage1","stage1"]);assert!(Progress::parse(&v).is_err());}
#[test]fn completed_adventure_does_not_double_count_wins(){let mut b=fixture();let pos=Decoder::parse(&b).unwrap().spans[&0x30].0;b[pos..pos+4].copy_from_slice(&8u32.to_le_bytes());let d=Decoder::parse(&b).unwrap();let p=d.progress().unwrap();let b2=d.apply(&p).unwrap();assert_eq!(Decoder::parse(&b2).unwrap().int(0x30),8);}
fn setup()->(PathBuf,PathBuf){let root=std::env::temp_dir().join(format!("peggle-progress-tests-{}",id()));let docs=root.join("Documents");let guest=Manager::guest(&docs);let u=guest.join("Documents/userdata");fs::create_dir_all(&u).unwrap();let mut idx=1u32.to_le_bytes().to_vec();idx.extend(1u16.to_le_bytes());idx.extend(6u16.to_le_bytes());idx.extend(b"Tester");idx.extend(1u32.to_le_bytes());idx.extend(1u32.to_le_bytes());fs::write(u.join("users.dat"),idx).unwrap();fs::write(u.join("user1.dat"),fixture()).unwrap();fs::write(u.join("stage1.sav"),b"local suspended game stays byte-identical").unwrap();(root,docs)}
#[test]fn transactional_import_retains_board_and_rollback_and_rejects_live_session(){let (root,docs)=setup();let mut m=Manager::open(&docs).unwrap();let original=m.active_guest(&m.state().unwrap()).unwrap();let result=m.preview_progress(&advanced().document("Different device profile name")).unwrap();assert_eq!(result["profile"],"Tester");let token=result["token"].as_str().unwrap();assert!(m.restore_raw(token,false).is_err());m.restore_raw(token,true).unwrap();let current=m.active_guest(&m.state().unwrap()).unwrap();assert_eq!(fs::read(current.join("Documents/userdata/stage1.sav")).unwrap(),fs::read(original.join("Documents/userdata/stage1.sav")).unwrap());let exported=m.export_progress().unwrap();assert_eq!(Progress::parse(&exported["document"]).unwrap(),advanced());let duplicate=m.preview_progress(&exported["document"]).unwrap();assert_eq!(duplicate["changed"],false);m.rollback(true).unwrap();assert_eq!(fs::read(m.active_guest(&m.state().unwrap()).unwrap().join("Documents/userdata/user1.dat")).unwrap(),fixture());let lease=m.begin_game().unwrap();assert!(Manager::open(&docs).is_err());drop(lease);fs::remove_dir_all(root).unwrap();}
#[test]fn stale_preview_cannot_overwrite_a_new_local_save(){let (root,docs)=setup();let mut m=Manager::open(&docs).unwrap();let result=m.preview_progress(&advanced().document("Tester")).unwrap();let u=m.active_guest(&m.state().unwrap()).unwrap().join("Documents/userdata/user1.dat");let mut b=fixture();b[12]=1;fs::write(&u,&b).unwrap();assert!(m.restore_raw(result["token"].as_str().unwrap(),true).is_err());assert_eq!(fs::read(&u).unwrap(),b);drop(m);fs::remove_dir_all(root).unwrap();}

#[test]fn level_names_have_a_canonical_cloud_representation(){let p=advanced();let mut v=p.document("Tester");v["classic"]["cleared_levels"]=json!(["STAGE1"]);let other=Progress::parse(&v).unwrap();assert_eq!(p.merged(&other),other.merged(&p));assert_eq!(p,other);}

#[test]fn case_normalization_never_rewrites_unchanged_local_sets(){let b=fixture();let d=Decoder::parse(&b).unwrap();let mut b=d.apply(&advanced()).unwrap();let at=b.windows(6).position(|v|v==b"stage1").unwrap();b[at..at+6].copy_from_slice(b"STAGE1");let d=Decoder::parse(&b).unwrap();let mut p=d.progress().unwrap();assert_eq!(d.apply(&p).unwrap(),b);p.nights.level=4;let out=d.apply(&p).unwrap();let d2=Decoder::parse(&out).unwrap();assert_eq!(d.field_bytes(0x14c),d2.field_bytes(0x14c));}

#[test]fn v1_migrates_without_inventing_a_checkpoint(){let p=advanced();let mut v=p.document("Tester");v["schema"]=json!(1);v["scope"]=json!("unlock-progress");for key in ["classic","nights"]{v[key].as_object_mut().unwrap().remove("checkpoint");}let old=Progress::parse(&v).unwrap();assert_eq!(old,p);assert_eq!(old.document("Tester")["schema"],2);}
#[test]fn phone_checkpoint_advances_hd_and_keeps_other_fields(){let phone=include_bytes!("../../../../tests/progress/phone-2-1-v25.dat");let hd=include_bytes!("../../../../tests/progress/hd-1-3-v25.dat");let a=Decoder::parse(phone).unwrap();let b=Decoder::parse(hd).unwrap();let merged=a.progress().unwrap().merged(&b.progress().unwrap());assert_eq!(merged.classic.checkpoint,Some((1,0)));assert_eq!(merged,a.progress().unwrap().merged(&merged));assert_eq!(merged,b.progress().unwrap().merged(&a.progress().unwrap()));let output=b.apply(&merged).unwrap();let d=Decoder::parse(&output).unwrap();assert_eq!((d.int(0x18),d.int(0x1c)),(1,0));for k in [0x280,0x284,0x288,0x188,0x204,0x294,0x298]{assert_eq!(b.field_bytes(k),d.field_bytes(k));}}
#[test]fn advancing_checkpoint_removes_only_its_board_and_rollback_restores_it(){let (root,docs)=setup();let mut m=Manager::open(&docs).unwrap();let original=m.active_guest(&m.state().unwrap()).unwrap();let u=original.join("Documents/userdata");fs::write(u.join("user1.dat"),include_bytes!("../../../../tests/progress/hd-1-3-v25.dat")).unwrap();for name in ["stagenights1.sav","stage2.sav"]{fs::write(u.join(name),b"unrelated board").unwrap();}let incoming=Decoder::parse(include_bytes!("../../../../tests/progress/phone-2-1-v25.dat")).unwrap().progress().unwrap();let preview=m.preview_progress(&incoming.document("Duo")).unwrap();assert_eq!(preview["advanced_campaigns"],json!(["classic"]));m.restore_raw(preview["token"].as_str().unwrap(),true).unwrap();let current=m.active_guest(&m.state().unwrap()).unwrap().join("Documents/userdata");assert!(!current.join("stage1.sav").exists());for name in ["stagenights1.sav","stage2.sav"]{assert_eq!(fs::read(current.join(name)).unwrap(),b"unrelated board");}
 fs::write(current.join("stage1.sav"),b"new board at same checkpoint").unwrap();let again=m.preview_progress(&incoming.document("Duo")).unwrap();assert_eq!(again["changed"],false);assert_eq!(again["advanced_campaigns"],json!([]));assert_eq!(fs::read(current.join("stage1.sav")).unwrap(),b"new board at same checkpoint");m.rollback(true).unwrap();let restored=m.active_guest(&m.state().unwrap()).unwrap();assert!(restored.join("Documents/userdata/stage1.sav").exists());assert_eq!(fs::read(restored.join("Documents/userdata/user1.dat")).unwrap(),include_bytes!("../../../../tests/progress/hd-1-3-v25.dat"));drop(m);fs::remove_dir_all(root).unwrap();}
#[test]fn nights_checkpoint_advances_independently_and_invalid_checkpoints_reject(){let b=fixture();let d=Decoder::parse(&b).unwrap();let mut p=advanced();p.nights.checkpoint=Some((12,3));let output=d.apply(&p).unwrap();let out=Decoder::parse(&output).unwrap();assert_eq!((out.int(0x294),out.int(0x298)),(12,3));assert_eq!(out.int(0x18),u32::MAX);let mut v=p.document("Tester");v["nights"]["checkpoint"]["stage"]=json!(13);assert!(Progress::parse(&v).is_err());v["nights"]["checkpoint"]=json!({"stage":0,"level":0});assert!(Progress::parse(&v).is_err());}

#[test]fn canonical_exchange_identifies_remote_changes_without_live_save_mutation(){let (root,docs)=setup();let m=Manager::open(&docs).unwrap();let local=m.export_progress().unwrap();assert_eq!(local["profile_id"],1);let lease=m.begin_game().unwrap();let source=lease.progress_snapshot(1).unwrap();assert_eq!(source["document"],local["document"]);let remote=advanced().document("Other device");let merged=exchange(&json!({"local":source["document"],"remote":remote})).unwrap();assert_eq!(merged["remote_adds"],true);assert_eq!(merged["upload_needed"],false);assert_eq!(lease.progress_snapshot(1).unwrap(),source);assert!(lease.progress_snapshot(900).is_err());let again=exchange(&json!({"local":merged["document"],"remote":remote})).unwrap();assert_eq!(again["remote_adds"],false);assert_eq!(again["upload_needed"],false);assert!(Manager::open(&docs).is_err());drop(lease);fs::remove_dir_all(root).unwrap();}

#[test]fn deferred_cloud_data_is_not_new_just_because_local_progress_advances(){let mut deferred=advanced();deferred.nights.aced.insert("level20".into());let mut local=advanced();local.classic.stage=3;local.classic.level=0;let incoming=local.merged(&deferred);let covered=local.merged(&deferred);let r=exchange(&json!({"local":covered.document("Local"),"remote":incoming.document("Cloud")})).unwrap();assert_eq!(r["remote_adds"],false);let mut newer=incoming;newer.nights.stage=15;let r=exchange(&json!({"local":covered.document("Local"),"remote":newer.document("Cloud")})).unwrap();assert_eq!(r["remote_adds"],true);}

#[test]fn selection_merge_reads_profile_and_keeps_local_fields(){
 let(root,docs)=setup();let mut m=Manager::open(&docs).unwrap();let input=root.join("user8.dat");fs::write(&input,include_bytes!("../../../../tests/progress/phone-2-1-v25.dat")).unwrap();
 let before=m.export_progress().unwrap();let preview=m.preview_merge_selection(&[input],false).unwrap();assert_eq!(preview["after"]["classic_checkpoint"],"2-1");assert_eq!(m.export_progress().unwrap()["document"],before["document"]);assert!(m.restore_raw(preview["token"].as_str().unwrap(),false).is_err());m.restore_raw(preview["token"].as_str().unwrap(),true).unwrap();assert_eq!(m.export_progress().unwrap()["summary"]["classic_checkpoint"],"2-1");drop(m);fs::remove_dir_all(root).unwrap();
}
#[test]fn folder_export_roundtrips_and_merge_zip_respects_selected_profile(){
 let(root,docs)=setup();let mut m=Manager::open(&docs).unwrap();fs::remove_file(Manager::guest(&docs).join("Documents/userdata/stage1.sav")).unwrap();let folder=m.export_folder().unwrap();assert_eq!(fs::read(folder.join("userdata/user1.dat")).unwrap(),fixture());assert!(folder.join("manifest.json").exists());assert!(!folder.join("Library").exists());
 let preview=m.preview_merge_selection(&[folder],false).unwrap();assert_eq!(preview["changed"],false);let zip=m.export().unwrap();assert_eq!(m.preview_merge_selection(&[zip],true).unwrap()["changed"],false);
 let input=root.join("user8.dat");fs::write(&input,fixture()).unwrap();let input2=root.join("user9.dat");fs::write(&input2,fixture()).unwrap();assert!(m.preview_merge_selection(&[input,input2],false).is_err());drop(m);fs::remove_dir_all(root).unwrap();
}

#[test]
fn individual_challenge_completions_merge_independently_in_both_campaigns() {
 let bytes=fixture();let decoder=Decoder::parse(&bytes).unwrap();
 let mut a=decoder.progress().unwrap();let mut b=a.clone();
 a.classic.trophies.extend([1,3]);b.classic.trophies.extend([2,3]);
 a.nights.trophies.extend([1,5]);b.nights.trophies.extend([2]);
 let merged=a.merged(&b);
 assert_eq!(merged.classic.trophies,BTreeSet::from([1,2,3]));
 assert_eq!(merged.nights.trophies,BTreeSet::from([1,2,5]));
 let restored=Progress::parse(&merged.document("Tester")).unwrap();
 let output=decoder.apply(&restored).unwrap();let check=Decoder::parse(&output).unwrap();
 assert_eq!(check.list(0xa8,false).unwrap(),json!([1,2,3]));
 assert_eq!(check.list(0x128,false).unwrap(),json!([1,2,5]));
 assert_eq!(decoder.field_bytes(0xc0),check.field_bytes(0xc0));
 assert_eq!(decoder.field_bytes(0x188),check.field_bytes(0x188));
 assert_eq!(restored,restored.merged(&a).merged(&b));
}
